import Foundation
import PaletteCore

/// Exports Palette's web apps to a small Lua table that Hammerspoon loads.
/// The file is generated output: shortcuts stay owned by Palette.
public enum HammerspoonExport {
    public static var defaultDirectory: URL {
        FileManager.default.homeDirectoryForCurrentUser.appendingPathComponent(".hammerspoon")
    }

    public static func render(_ apps: [WebApp]) -> String {
        var lines = [
            "-- Generated by Palette. Do not edit; use /web in Palette instead.",
            "-- Shortcut format: ctrl+alt+f. Manage them with /web, then \u{2318}K.",
            "return {",
        ]
        for app in apps.sorted(by: { $0.name.localizedCaseInsensitiveCompare($1.name) == .orderedAscending }) {
            var fields = [
                "name = \"\(escape(app.name))\"",
                "url = \"\(escape(app.url))\"",
            ]
            if let shortcut = app.shortcut {
                fields.append("shortcut = \"\(escape(shortcut))\"")
            }
            lines.append("  { " + fields.joined(separator: ", ") + " },")
        }
        lines.append("}")
        lines.append("")
        return lines.joined(separator: "\n")
    }

    /// Writes the generated file only when Hammerspoon's config directory
    /// exists, so the app does not create a stray `~/.hammerspoon`.
    @discardableResult
    public static func write(_ apps: [WebApp], directory: URL = defaultDirectory) throws -> URL? {
        let manager = FileManager.default
        var isDirectory: ObjCBool = false
        guard manager.fileExists(atPath: directory.path, isDirectory: &isDirectory), isDirectory.boolValue else {
            return nil
        }
        let url = directory.appendingPathComponent("palette-webapps.lua")
        try render(apps).write(to: url, atomically: true, encoding: .utf8)
        return url
    }

    private static func escape(_ value: String) -> String {
        value
            .replacingOccurrences(of: "\\", with: "\\\\")
            .replacingOccurrences(of: "\"", with: "\\\"")
            .replacingOccurrences(of: "\n", with: "\\n")
    }
}
